    for _ in range(t):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        xor_sum = 0
        for _ in range(n):
            a = int(next(iterator))

            if a % 2 == 0:
                # Even numbers: g(a) = 0, doesn't affect XOR
                continue
            elif a == 1:
                # g(1) = 1
                xor_sum ^= 1
            else:
                # Odd > 1: g(a) = pi[spf[a]]
                xor_sum ^= pi[spf[a]]

